    "content": "\u201E\u10D0\u10D3\u10D0\u10DB\u10D8\u10D0\u10DC\u10D8\u10E1 \u10DC\u10D0\u10DB\u10D3\u10D5\u10D8\u10DA\u10D8 \u10E1\u10D8\u10DB\u10D3\u10D8\u10D3\u10E0\u10D4 \u10D8\u10E1\u10D0\u10D0, \u10E0\u10D0\u10DB\u10D3\u10D4\u10DC\u10E1 \u10E8\u10D4\u10E3\u10EB\u10DA\u10D8\u10D0 \u10D2\u10D0\u10E1\u10EA\u10D4\u10E1.\u201C",
