    "content": "\u10E8\u10D4\u10EE\u10D5\u10D4\u10D3\u10E0\u10D8\u10E1 \u10E8\u10D4\u10DB\u10D3\u10D4\u10D2 3 \u10DB\u10D7\u10D0\u10D5\u10D0\u10E0\u10D8 \u10DE\u10E3\u10DC\u10E5\u10E2\u10D8 \u10DB\u10D0\u10E8\u10D8\u10DC\u10D5\u10D4 \u10E9\u10D0\u10D8\u10DC\u10D8\u10E8\u10DC\u10D4.",
