    "content": "\u10E1\u10D0\u10D9\u10D5\u10D4\u10D1\u10D8 \u10D9\u10DD\u10DC\u10E2\u10D4\u10D8\u10DC\u10D4\u10E0\u10D4\u10D1\u10E8\u10D8 \u10EC\u10D8\u10DC\u10D0\u10E1\u10EC\u10D0\u10E0 \u10D2\u10D0\u10D0\u10DC\u10D0\u10EC\u10D8\u10DA\u10D4 \u2014 \u10EF\u10D0\u10DC\u10E1\u10D0\u10E6\u10D0\u10D3 \u10ED\u10D0\u10DB\u10D0 \u10D2\u10D0\u10D2\u10D8\u10D0\u10D3\u10D5\u10D8\u10DA\u10D3\u10D4\u10D1\u10D0.",
