    "content": "\u201E\u10D4\u10ED\u10D5\u10D8 \u10EA\u10DD\u10D3\u10DC\u10D8\u10E1 \u10DB\u10E2\u10D4\u10E0\u10D8\u10D0 \u10DB\u10EE\u10DD\u10DA\u10DD\u10D3 \u10DB\u10D0\u10E8\u10D8\u10DC, \u10E0\u10DD\u10EA\u10D0 \u10D9\u10D8\u10D7\u10EE\u10D5\u10D0\u10E1 \u10D0\u10E0 \u10DB\u10DD\u10F0\u10E7\u10D5\u10D4\u10D1\u10D0 \u10EB\u10D8\u10D4\u10D1\u10D0.\u201C",
