    "content": "\u201E\u10D3\u10D8\u10D3\u10D8 \u10D0\u10D3\u10D0\u10DB\u10D8\u10D0\u10DC\u10D8 \u10E1\u10EE\u10D5\u10D0\u10E1 \u10DE\u10D0\u10E2\u10D0\u10E0\u10D0 \u10D0\u10E0 \u10EE\u10D3\u10D8\u10E1, \u10E0\u10D0\u10D7\u10D0 \u10D7\u10D0\u10D5\u10D0\u10D3 \u10D3\u10D8\u10D3\u10D8 \u10D2\u10D0\u10DB\u10DD\u10E9\u10DC\u10D3\u10D4\u10E1.\u201C",
