    "category": "\u10D0\u10D5\u10E2\u10DD\u10DB\u10DD\u10D1\u10D8\u10DA\u10D4\u10D1\u10D8",
    "content": "\u10EB\u10E0\u10D0\u10D5\u10D8\u10E1 \u201E\u10E9\u10D0\u10E5\u10E0\u10DD\u10D1\u10D0\u201C \u10DB\u10DD\u10EB\u10E0\u10D0\u10DD\u10D1\u10D8\u10E1\u10D0\u10E1 \u10E7\u10DD\u10D5\u10D4\u10DA\u10D7\u10D5\u10D8\u10E1 \u10D3\u10D8\u10D0\u10D2\u10DC\u10DD\u10E1\u10E2\u10D8\u10E0\u10D4\u10D1\u10D0\u10E1 \u10E1\u10D0\u10ED\u10D8\u10E0\u10DD\u10D4\u10D1\u10E1.",
