    "category": "\u10EA\u10D8\u10E2\u10D0\u10E2\u10D0",
    "content": "\u201E\u10E4\u10D8\u10E5\u10E0\u10D8 \u10D0\u10E0\u10D8\u10E1 \u10D3\u10D0\u10E1\u10D0\u10EC\u10E7\u10D8\u10E1\u10D8; \u10DB\u10DD\u10E5\u10DB\u10D4\u10D3\u10D4\u10D1\u10D0 \u2014 \u10E8\u10D4\u10D3\u10D4\u10D2\u10D8\u10E1 \u10DB\u10D8\u10D6\u10D4\u10D6\u10D8.\u201C",
