    "content": "\u201E\u10EC\u10D0\u10E0\u10DB\u10D0\u10E2\u10D4\u10D1\u10D0 \u10EE\u10E8\u10D8\u10E0\u10D0\u10D3 \u10E3\u10D1\u10E0\u10D0\u10DA\u10DD\u10D3 \u10D3\u10D0\u10DF\u10D8\u10DC\u10D4\u10D1\u10E3\u10DA\u10D8 \u10DB\u10EA\u10D3\u10D4\u10DA\u10DD\u10D1\u10D0\u10D0.\u201C",
