    "content": "\u201E\u10D5\u10D8\u10DC\u10EA \u10E1\u10D0\u10D9\u10E3\u10D7\u10D0\u10E0 \u10D7\u10D0\u10D5\u10E1 \u10D8\u10EA\u10DC\u10DD\u10D1\u10E1, \u10D1\u10E0\u10EB\u10D4\u10DC\u10D8\u10D0.\u201C \u2014 \u10DA\u10D0\u10DD-\u10EB\u10D8",
